2. Create `test/area.test.ts` with exactly this content:
```
import assert from "node:assert/strict";
import { test } from "node:test";
import worker from "../src/index.ts";

type Converted = { result: number; display: string };

async function convert(from: string, to: string, v: number): Promise<Converted> {
  const res = await worker.fetch(new Request(`http://localhost/api/convert?c=area&from=${from}&to=${to}&v=${v}`));
  assert.equal(res.status, 200);
  return (await res.json()) as Converted;
}

// result is the converted number; display is formatValue(result), so it follows the shared number format.
const cases = [
  { from: "ha", to: "m2", v: 1, result: 10000, display: "10000.00" },
  { from: "ac", to: "m2", v: 1, result: 4046.8564224, display: "4046.86" },
  { from: "mi2", to: "ha", v: 1, result: 258.998811034, display: "259.00" },
];

for (const c of cases) {
  test(`area: ${c.v} ${c.from} is ${c.result} ${c.to}`, async () => {
    const got = await convert(c.from, c.to, c.v);
    assert.ok(Math.abs(got.result - c.result) <= 1e-9 * Math.abs(c.result), `got ${got.result}`);
  });
  test(`area: ${c.v} ${c.from} to ${c.to} displays as ${c.display}`, async () => {
    assert.equal((await convert(c.from, c.to, c.v)).display, c.display);
  });
}

test("area has a converter page", async () => {
  const res = await worker.fetch(new Request("http://localhost/c/area"));
  assert.equal(res.status, 200);
  assert.ok((await res.text()).includes("Area"));
});
```

